result_description_template:
REQ content={{.Content}} | kind={{.Kind}} | anime={{printf "%t" .IsAnime}} | score={{score .Score}} | top={{score .TopScore}}
RAW {{.ReleaseTitle}}
PARSED title={{.ParsedTitle}} | year={{.Year}} | episode={{.EpisodeCode}} | res={{.Resolution}} | quality={{.Quality}} | codec={{.Codec}} | bit={{.BitDepth}} | hdr={{join .HDR ","}} | audio={{join .Audio ","}} | channels={{join .Channels ","}}
META group={{.Group}} | edition={{.Edition}} | network={{.Network}} | indexer={{.Indexer}} | size={{size .Size}} | age={{.Age}} | grabs={{.Grabs}}
FAILOVER variants={{.Variants}} | indexers={{join .VariantIndexers ","}}
AVAIL status={{.Availability.Status}} | known={{printf "%t" .Availability.Known}} | backbone={{printf "%t" .Availability.OnMyBackbone}} | checkedDays={{.Availability.CheckedDaysAgo}} | compression={{.Availability.Compression}}
SEADEX checked={{printf "%t" .Seadex.Checked}} | known={{printf "%t" .Seadex.Known}} | best={{printf "%t" .Seadex.Best}} | alt={{printf "%t" .Seadex.Alternative}}
LOCAL library={{printf "%t" .Library}} | verified={{printf "%t" .Verified}}{{if .Verified}} | video={{.Probed.VideoCodec}} | audio={{.Probed.AudioCodec}} | profile={{.Probed.Profile}} | bit={{.Probed.BitDepth}} | dynamicRange={{.Probed.DynamicRange}} | hdrFallback={{printf "%t" .Probed.HasHDRFallback}}{{end}}
RULES{{range .MatchedRules}} [{{.Name}}={{score .Score}}]{{else}} none{{end}}
